"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4830],{74830:a=>{a.exports=JSON.parse('{"slug":"sankcii-ssha-platezhnaya-set-a7","locale":"zh","title":"美国拟禁止银行经A7支付网络数百家公司转账","description":"美国财政部十月1日将A7网络认定为犯罪组织，并拟禁止经其子代理转账。分析对进口的影响。","blocks":[{"id":"b001","kind":"paragraph","text":"美国财政部于2026年十月1日将俄罗斯支付网络A7列为“重大跨国犯罪组织”。其金融犯罪部门FinCEN同时建议，禁止美国银行参与任何涉及A7“子代理”的转账。这些是网络用于处理俄罗斯客户付款的海外空壳公司。"},{"id":"b002","kind":"paragraph","text":"A7由摩尔多瓦商人伊兰\xb7绍尔和Promsvyazbank在2024年建立，转账手续费0.3%，发行锚定卢布的稳定币A7A5。俄罗斯境内的A7及稳定币自2025年八月受美国制裁，但付款继续经外国公司进行。美国当局还将网络与伊朗关联，称伊朗央行及革命卫队曾使用。FinCEN禁令依据反洗俄罗斯资金法律。"},{"id":"b003","kind":"paragraph","text":"A7规模大，在阿联酋、香港、土耳其、吉尔吉斯斯坦等有数百子代理，账户分布约83国435家银行。2025年一月至2026年六月处理超过$17十亿美元付款，且只是部分流量。网络称截至2026年一月累计转账7.5万亿卢布。Promsvyazbank估2025年上半年近12%的俄罗斯外贸经A7，FinCEN估2025全年近13%，相近。"},{"id":"b004","kind":"paragraph","text":"美国为何能阻断别国付款？不同国家银行的美元转账几乎总经过美国银行账户，像包裹经过分拣中心；中心不接，异国寄件与收件人之间也送不到。这称代理行账户，禁令切断A7子代理与中心。但不只美元：持有其账户的其他国家银行也怕受制裁，可能直接关闭所有币种账户。完整名单私下发给银行并持续增加。"},{"id":"b005","kind":"paragraph","text":"A7服务企业，制裁不直接扣普通人的钱包，间接通过进口价格传导。每个结算障碍都令跨境付款更慢更贵，企业把成本加入商品价，涨多少无法估计。A7在2025年已受美国制裁，仍通过新公司经营。"},{"id":"b006","kind":"paragraph","text":"FinCEN规则尚为草案，发布后有30天评论期。财政部希望其他国家与银行跟随，但结果未知。进口电子设备和零件买家不宜因新闻抢购：影响历时数月，且与卢布波动混合。但不能认为结算网络受打击与自己无关，因为昂贵付款最终体现在商品价格。"},{"id":"b007","kind":"heading","text":"A7支付网络是什么？"},{"id":"b008","kind":"paragraph","text":"伊兰\xb7绍尔与Promsvyazbank于2024年建立的国际转账系统，通过海外空壳公司处理俄罗斯企业付款，收0.3%手续费，并发行卢布稳定币A7A5。"},{"id":"b009","kind":"heading","text":"美国在2026年十月对A7采取什么措施？"},{"id":"b010","kind":"paragraph","text":"2026年十月1日财政部将A7认定跨国犯罪组织，FinCEN拟禁止美国银行经数百子代理转账。它们在83国约435家银行有账户。"},{"id":"b011","kind":"heading","text":"制裁A7会让进口更贵吗？"},{"id":"b012","kind":"paragraph","text":"可能，但幅度未知。俄罗斯近12–13%外贸通过A7，每增加障碍，结算更慢更贵，企业会把成本计入商品价。"}],"sources":[{"label":"美国制裁A7支付系统","url":"https://www.kommersant.ru/doc/8991793"},{"label":"美国准备禁止经A7数百家海外公司的付款","url":"https://thebell.io/ssha-gotovyat-zapret-na-platezhi-cherez-sotni-zarubezhnykh-kompaniy-a7-po-otsenke-psb-cherez-etu-set-shlo-pochti-12-vneshney-torgovli-rossii"},{"label":"针对A7网络子代理的特别措施建议","url":"https://www.fincen.gov/system/files/2026-10/9714-A7-NETWORK-NPRM.pdf"}],"sourceBodySha256":"e928692ceb98a757973abed5533e72f30df7536893758054b08fc807c779360a"}')}}]);